{
  "domain_type": "computational",
  "tokens": ["semiprime", "prime factor", "factorization", "verification", "unique factorization"],
  "boundary": "The semiprime N = p × q forms a closed multiplicative container; the factorization process opens this container, extracts the prime factors, verifies their product reconstructs N, and reseals the boundary with the fixed invariant of unique factorization.",
  "opcodes": {
    "VINIT": {
      "element": "uninitialized semiprime register",
      "justification": "Before any semiprime is named or loaded, the computational state is void — no integer, no factors, no verification status exists."
    },
    "TANCH": {
      "element": "semiprime boundary N",
      "justification": "The semiprime N acts as a composite container (topology 𐑰) that bounds exactly two prime factors in a hierarchical multiplicative tree; TANCH anchors this closed boundary as the terminal container for the operation."
    },
    "AFWD": {
      "element": "factorization algorithm (trial division, ECM, GNFS, etc.)",
      "justification": "The forward morphism advances from the composite semiprime toward its prime constituents through irreversible structural decomposition (relational 𐑑), transforming N into the pair (p, q)."
    },
    "AREV": {
      "element": "multiplication verification p × q = N",
      "justification": "The reverse morphism descends from the candidate factors back to the original semiprime by multiplying them, clearing the register of intermediate state while retaining the open Frobenius frame for the return."
    },
    "CLINK": {
      "element": "compositional link between factorization and verification",
      "justification": "CLINK chains the forward factorization and reverse verification into a single sequential process that preserves the return structure (fidelity 𐑐), ensuring the split factors recombine to the original N."
    },
    "IMSCRIB": {
      "element": "self-recognition of semiprime as product of its primes",
      "justification": "The semiprime knows its own prime structure; IMSCRIB inscribes this identity (N = p × q) into the operation itself, making the factorization available to its own verification (criticality 𐑢 = subcritical, deterministic)."
    },
    "FSPLIT": {
      "element": "semiprime N splitting into prime factor arms p and q",
      "justification": "Frobenius comultiplication δ opens the composite N into two arms: the T-arm carries the first prime factor p, the F-arm carries the second prime factor q (granularity 𐑲 = local, single event)."
    },
    "FFUSE": {
      "element": "verified recombination of p and q into N",
      "justification": "Frobenius multiplication μ fuses the transformed arms back into the single state N, rejoining p and q through the multiplication check; conflicting evidence on arms (e.g., one factor prime, one composite) would rejoin to B, but correct factorization rejoins to T."
    },
    "EVALT": {
      "element": "prime factor confirmed (p is prime, q is prime)",
      "justification": "Deposits constructive truth T on each arm when the candidate factor passes primality testing — affirmative evidence that the arm holds a genuine prime."
    },
    "EVALF": {
      "element": "candidate factor rejected as composite",
      "justification": "Deposits constructive falsity F when a candidate factor fails primality testing — negative evidence that the arm does not hold a prime, triggering backtracking or algorithm continuation."
    },
    "ENGAGR": {
      "element": "dialetheic state when factorization is uncertain or contradictory",
      "justification": "Holds both T and F simultaneously (B state) when evidence conflicts — e.g., a probabilistic primality test returns probable prime but deterministic proof is pending, or when the semiprime is actually a prime power masquerading as semiprime; the Brass Vessel (stoichiometry 𐑳 = asymmetric) contains this contradiction without explosion."
    },
    "IFIX": {
      "element": "fixed unique factorization record",
      "justification": "Permanently fixes the winding invariant (protection 𐑭 = integer-winding) of the verified factorization N = p × q as an append-only ROM record; the unique factorization theorem guarantees this invariant cannot be continuously deformed."
    }
  },
  "frobenius": {
    "split_element": "semiprime N splitting into prime factor arms p and q",
    "split_input": "the composite semiprime N as a single multiplicative object",
    "split_outputs": ["T-arm: first prime factor p with primality evidence", "F-arm: second prime factor q with primality evidence"],
    "fuse_element": "verified recombination of p and q into N via multiplication check",
    "fuse_result": "the single state N reconstructed from verified primes p and q; if both arms carry T (both factors prime), rejoins to T; if one arm carries F (factor composite), rejoins to F; if arms carry conflicting evidence, rejoins to B",
    "rejoin_note": "On the T-arm, the factorization algorithm computes p and EVALT deposits prime confirmation; on the F-arm, it computes q and EVALT deposits prime confirmation; AREV (multiplication verification) runs on the fused result; CLINK composes the forward and reverse passes; the fork closes only when p × q = N is verified."
  },
  "registers": {
    "void": "no semiprime loaded, no factors computed, no verification attempted — the empty computational state before initialization",
    "true": "semiprime successfully separated into two verified prime factors p and q with p × q = N confirmed — affirmative factorization complete",
    "false": "factorization failed — candidate factors are composite, or p × q ≠ N, or no factors found within bounds — negative result",
    "both": "dialetheic state: factorization algorithm produces probable primes but deterministic proof incomplete, or semiprime is a prime power (p = q) creating ambiguity between distinct and repeated factors, or probabilistic test conflicts with deterministic check — both success and failure evidence held simultaneously in the Brass Vessel"
  },
  "sequence": [
    "VINIT: initialize void computational state — no semiprime, no factors, no verification",
    "IMSCRIB: inscribe the self-referential identity of the semiprime as a composite container awaiting factorization",
    "TANCH: anchor the semiprime boundary N as the closed multiplicative container (topology 𐑰) that will hold the operation",
    "FSPLIT: split the semiprime N into two arms — T-arm for first prime factor p, F-arm for second prime factor q",
    "AFWD: on T-arm, execute forward factorization morphism to compute candidate p (trial division, ECM, etc.)",
    "EVALT: on T-arm, deposit T when primality test confirms p is prime",
    "AFWD: on F-arm, execute forward factorization morphism to compute candidate q = N/p",
    "EVALT: on F-arm, deposit T when primality test confirms q is prime",
    "ENGAGR: on either arm, if probabilistic and deterministic tests conflict, engage B-state holding both prime and composite evidence",
    "CLINK: compose the two factor computations into a single sequential verification structure",
    "AREV: execute reverse morphism — multiply p × q to verify reconstruction of N, clearing register but retaining open Frobenius frame",
    "EVALF: if p × q ≠ N, deposit F on the fused result (verification failed)",
    "EVALT: if p × q = N, deposit T on the fused result (verification succeeded)",
    "FFUSE: fuse the verified arms back into the single state N — rejoining T+T→T, T+F→F, or conflicting→B",
    "IMSCRIB: inscribe the verified identity N = p × q into the operation as self-recognition of unique factorization",
    "IFIX: permanently fix the winding invariant of the unique factorization as ROM record (protection 𐑭)",
    "TANCH: close the semiprime boundary with the fixed factorization sealed inside — operation complete"
  ],
  "m⊙²": {
    "compiler": "the factorization algorithm selector (trial division → ECM → GNFS) that translates the semiprime bit-length into concrete computational operations",
    "ipc": "the Frobenius split/fuse channels carrying prime candidates between factorization and verification arms, with CLINK composing the forward/reverse passes",
    "memory": "the register holding the semiprime N, candidate factors p and q, and the Belnap evidence state (N/T/F/B) across the split/fuse cycle",
    "scheduler": "the route ladder (Saturn→Jupiter→Mars→Sun→Venus→Mercury→Moon→Ogdoad) determining the order of factorization methods and verification steps",
    "alfs": "the unique factorization theorem (Fundamental Theorem of Arithmetic) as the canonical bootstrap store guaranteeing the invariant"
  },
  "entropy": {
    "cost": "computational work of factorization (subexponential for GNFS, polynomial for verification) and the Landauer cost of fixing the IFIX record",
    "pre": "semiprime N as unstructured composite with unknown factors — high algorithmic entropy",
    "post": "verified factorization N = p × q with fixed invariant — low algorithmic entropy, structural order restored",
    "verdict": "ΔS ≈ 0 — the factorization process is entropy-conservative because the information gained (prime factors) exactly equals the information lost (composite ambiguity), and the unique factorization theorem guarantees the cycle N → (p,q) → N is information-preserving; the IFIX record fixes the invariant without thermodynamic cost beyond Landauer minimum"
  }
}

